define(["core/ajax","core/notification"],function(Ajax,Notification){const init=function(bookflowId){document.addEventListener("submit",function(event){const form=event.target.closest("[data-region='bookflow-note-form']");if(!form){return}event.preventDefault();const data=new FormData(form);const selection=window.getSelection();Ajax.call([{methodname:"mod_bookflow_create_note",args:{bookflowid:bookflowId,chapterid:Number(data.get("chapterid")||0),contentid:Number(data.get("contentid")||0),note:data.get("note"),selectiontext:data.get("selectiontext")||(selection?selection.toString().trim():"")}}])[0].then(function(){form.reset();return true}).catch(Notification.exception)})};return{init:init}});